Definition model_ivs_wf (m : Model) : Prop :=
  ivs_wf (vm_maps (m_vmmaps m)) /\ ivs_wf (vm_noaccess (m_vmmaps m)) /\ ivs_wf (m_vm_lazy m)
  /\ init_sp_ok (m_vmmaps m).  (* [comment removed for export] *)

